namespace Polars.Benchmarks.Tpch;

// TPC-H tables as generated by DuckDB's tpch extension (same shapes as Polars.TPCH.Tests).

public record Customer(long c_custkey, string c_name, string c_address, int c_nationkey, string c_phone, decimal c_acctbal, string c_mktsegment, string c_comment);

public record LineItem(
    long l_orderkey, long l_partkey, long l_suppkey, long l_linenumber,
    decimal l_quantity, decimal l_extendedprice, decimal l_discount, decimal l_tax,
    string l_returnflag, string l_linestatus,
    DateOnly l_shipdate, DateOnly l_commitdate, DateOnly l_receiptdate,
    string l_shipinstruct, string l_shipmode, string l_comment);

public record Nation(int n_nationkey, string n_name, int n_regionkey, string n_comment);

public record Orders(long o_orderkey, long o_custkey, string o_orderstatus, decimal o_totalprice, DateOnly o_orderdate, string o_orderpriority, string o_clerk, int o_shippriority, string o_comment);

public record Region(int r_regionkey, string r_name, string r_comment);

public record Supplier(long s_suppkey, string s_name, string s_address, int s_nationkey, string s_phone, decimal s_acctbal, string s_comment);
